"use client"

import Link from "next/link"
import { ShoppingCart, Menu, X, Zap } from "lucide-react"
import { useCart } from "@/context/cart"
import { useState } from "react"

const navLinks = [
  { href: "/", label: "Home" },
  { href: "/products", label: "Products" },
]

export default function Navbar() {
  const { count } = useCart()
  const [menuOpen, setMenuOpen] = useState(false)

  return (
    <header className="sticky top-0 z-50 bg-white/90 backdrop-blur border-b border-zinc-200 dark:bg-zinc-950/90 dark:border-zinc-800">
      <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between gap-4">
        {/* Logo */}
        <Link href="/" className="flex items-center gap-2 font-bold text-xl tracking-tight text-zinc-900 dark:text-white">
          <Zap className="w-5 h-5 text-indigo-600" />
          ShopNext
        </Link>

        {/* Desktop nav */}
        <nav className="hidden sm:flex items-center gap-6 text-sm font-medium text-zinc-600 dark:text-zinc-400">
          {navLinks.map((l) => (
            <Link
              key={l.href}
              href={l.href}
              className="hover:text-zinc-900 dark:hover:text-white transition-colors"
            >
              {l.label}
            </Link>
          ))}
        </nav>

        {/* Cart + mobile toggle */}
        <div className="flex items-center gap-3">
          <Link
            href="/cart"
            aria-label={`Cart, ${count} item${count !== 1 ? "s" : ""}`}
            className="relative flex items-center justify-center w-10 h-10 rounded-full hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors"
          >
            <ShoppingCart className="w-5 h-5 text-zinc-700 dark:text-zinc-300" />
            {count > 0 && (
              <span className="absolute -top-0.5 -right-0.5 min-w-[18px] h-[18px] flex items-center justify-center rounded-full bg-indigo-600 text-white text-[10px] font-bold px-1">
                {count > 99 ? "99+" : count}
              </span>
            )}
          </Link>

          <button
            className="sm:hidden flex items-center justify-center w-10 h-10 rounded-full hover:bg-zinc-100 dark:hover:bg-zinc-800 transition-colors"
            onClick={() => setMenuOpen((v) => !v)}
            aria-label="Toggle menu"
            aria-expanded={menuOpen}
          >
            {menuOpen ? (
              <X className="w-5 h-5 text-zinc-700 dark:text-zinc-300" />
            ) : (
              <Menu className="w-5 h-5 text-zinc-700 dark:text-zinc-300" />
            )}
          </button>
        </div>
      </div>

      {/* Mobile menu */}
      {menuOpen && (
        <nav className="sm:hidden border-t border-zinc-100 dark:border-zinc-800 px-4 py-3 flex flex-col gap-3 text-sm font-medium bg-white dark:bg-zinc-950">
          {navLinks.map((l) => (
            <Link
              key={l.href}
              href={l.href}
              onClick={() => setMenuOpen(false)}
              className="text-zinc-700 dark:text-zinc-300 hover:text-zinc-900 dark:hover:text-white transition-colors"
            >
              {l.label}
            </Link>
          ))}
        </nav>
      )}
    </header>
  )
}

