"use client"

import Image from "next/image"
import Link from "next/link"
import { Star, ShoppingCart } from "lucide-react"
import type { Product } from "@/lib/products"
import { useCart } from "@/context/cart"

export default function ProductCard({ product }: { product: Product }) {
  const { add } = useCart()

  return (
    <div className="group relative flex flex-col bg-white dark:bg-zinc-900 rounded-2xl border border-zinc-100 dark:border-zinc-800 overflow-hidden shadow-sm hover:shadow-md transition-shadow">
      {/* Badge */}
      {product.badge && (
        <span className="absolute top-3 left-3 z-10 text-xs font-semibold px-2 py-0.5 rounded-full bg-indigo-600 text-white">
          {product.badge}
        </span>
      )}

      {/* Image */}
      <Link href={`/products/${product.id}`} className="block overflow-hidden bg-zinc-50 dark:bg-zinc-800">
        <Image
          src={product.image}
          alt={product.name}
          width={600}
          height={400}
          className="w-full h-52 object-cover group-hover:scale-105 transition-transform duration-300"
        />
      </Link>

      {/* Body */}
      <div className="flex flex-col flex-1 p-4 gap-2">
        <span className="text-xs text-indigo-600 font-medium uppercase tracking-wide">
          {product.category}
        </span>
        <Link href={`/products/${product.id}`}>
          <h3 className="font-semibold text-zinc-900 dark:text-white text-sm leading-snug hover:text-indigo-600 dark:hover:text-indigo-400 transition-colors line-clamp-2">
            {product.name}
          </h3>
        </Link>

        {/* Rating */}
        <div className="flex items-center gap-1 text-xs text-zinc-500 dark:text-zinc-400">
          <Star className="w-3.5 h-3.5 fill-amber-400 text-amber-400" />
          <span className="font-medium text-zinc-700 dark:text-zinc-300">{product.rating}</span>
          <span>({product.reviews.toLocaleString()})</span>
        </div>

        {/* Price */}
        <div className="flex items-baseline gap-2 mt-auto pt-2">
          <span className="text-lg font-bold text-zinc-900 dark:text-white">
            ${product.price.toFixed(2)}
          </span>
          {product.originalPrice && (
            <span className="text-sm line-through text-zinc-400">
              ${product.originalPrice.toFixed(2)}
            </span>
          )}
        </div>

        {/* Add to cart */}
        <button
          onClick={() => add(product)}
          className="mt-2 flex items-center justify-center gap-2 w-full py-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-700 active:scale-[0.98] text-white text-sm font-medium transition-all"
          aria-label={`Add ${product.name} to cart`}
        >
          <ShoppingCart className="w-4 h-4" />
          Add to Cart
        </button>
      </div>
    </div>
  )
}

