import { products, categories } from "@/lib/products"
import ProductCard from "@/components/ProductCard"
import type { Metadata } from "next"

export const metadata: Metadata = {
  title: "All Products — ShopNext",
  description: "Browse our full catalogue of premium products.",
}

export default async function ProductsPage({
  searchParams,
}: {
  searchParams: Promise<{ category?: string; sort?: string }>
}) {
  const { category, sort } = await searchParams

  let filtered = category ? products.filter((p) => p.category === category) : products

  if (sort === "price-asc") filtered = [...filtered].sort((a, b) => a.price - b.price)
  else if (sort === "price-desc") filtered = [...filtered].sort((a, b) => b.price - a.price)
  else if (sort === "rating") filtered = [...filtered].sort((a, b) => b.rating - a.rating)

  return (
    <div className="max-w-6xl mx-auto px-4 py-12">
      <h1 className="text-3xl font-bold text-zinc-900 dark:text-white mb-2">All Products</h1>
      <p className="text-zinc-500 dark:text-zinc-400 mb-8">
        {filtered.length} product{filtered.length !== 1 ? "s" : ""}{category ? ` in ${category}` : ""}
      </p>

      {/* Filters */}
      <div className="flex flex-wrap gap-3 mb-8">
        {/* Category filter */}
        <div className="flex flex-wrap gap-2">
          <FilterLink href="/products" label="All" active={!category} />
          {categories.map((cat) => (
            <FilterLink
              key={cat}
              href={`/products?category=${encodeURIComponent(cat)}${sort ? `&sort=${sort}` : ""}`}
              label={cat}
              active={category === cat}
            />
          ))}
        </div>

        {/* Sort */}
        <div className="ml-auto flex gap-2 flex-wrap">
          <SortLink href={`/products${category ? `?category=${encodeURIComponent(category)}&` : "?"}sort=price-asc`} label="Price ↑" active={sort === "price-asc"} />
          <SortLink href={`/products${category ? `?category=${encodeURIComponent(category)}&` : "?"}sort=price-desc`} label="Price ↓" active={sort === "price-desc"} />
          <SortLink href={`/products${category ? `?category=${encodeURIComponent(category)}&` : "?"}sort=rating`} label="Top Rated" active={sort === "rating"} />
        </div>
      </div>

      {filtered.length === 0 ? (
        <p className="text-zinc-500 dark:text-zinc-400 py-16 text-center">No products found.</p>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {filtered.map((product) => (
            <ProductCard key={product.id} product={product} />
          ))}
        </div>
      )}
    </div>
  )
}

function FilterLink({ href, label, active }: { href: string; label: string; active: boolean }) {
  return (
    <a
      href={href}
      className={`px-4 py-1.5 rounded-full text-sm font-medium border transition-colors ${
        active
          ? "bg-indigo-600 text-white border-indigo-600"
          : "bg-white dark:bg-zinc-900 text-zinc-600 dark:text-zinc-300 border-zinc-200 dark:border-zinc-700 hover:border-indigo-400 hover:text-indigo-600 dark:hover:text-indigo-400"
      }`}
    >
      {label}
    </a>
  )
}

function SortLink({ href, label, active }: { href: string; label: string; active: boolean }) {
  return (
    <a
      href={href}
      className={`px-3 py-1.5 rounded-full text-xs font-medium border transition-colors ${
        active
          ? "bg-zinc-900 dark:bg-white text-white dark:text-zinc-900 border-zinc-900 dark:border-white"
          : "bg-white dark:bg-zinc-900 text-zinc-500 dark:text-zinc-400 border-zinc-200 dark:border-zinc-700 hover:border-zinc-400"
      }`}
    >
      {label}
    </a>
  )
}

